package com.course.platform.service.impl;

import com.course.platform.infra.persistence.mapper.*;
import org.junit.jupiter.api.*;
import java.time.Duration;
import java.util.List;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;

/** 后台兜底使用实际周期事务，重复实例不产生重复结算，默认开关不访问未迁移表。 */
class CoursePrivateOperationsWorkerTest {
    @Test void twoWorkersAndManualRetryUseOneNextPeriod() throws Exception {var f=new CoursePrivateRenewalTransactionTest();try{f.setup();f.qualify();f.f.expire();var batch=mock(CoursePrivateContractTermMapper.class);when(batch.selectReconciliationBatch(0L,100)).thenReturn(List.of(f.source()));var time=new CoursePrivateOperationsTime(f.f.f.clock);var first=new CoursePrivateOperationsWorker(batch,f.f.f.f.wallets,f.f.f.service,f.f.service,time);var second=new CoursePrivateOperationsWorker(batch,f.f.f.f.wallets,f.f.f.service,f.f.service,time);for(var worker:List.of(first,second)){org.springframework.test.util.ReflectionTestUtils.setField(worker,"enabled",true);org.springframework.test.util.ReflectionTestUtils.setField(worker,"renewal",f.service);}var outcomes=f.f.f.f.concurrent(first::reconcile,second::reconcile);assertEquals(0,outcomes.stream().filter(RuntimeException.class::isInstance).count());assertEquals(2,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));var next=f.renew();Long app=f.application();f.f.f.auth(8);assertEquals(next.getId(),f.service.review(app,0,8L,"运营核验自动续期结果").getId());assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term WHERE renewal_source_term_id=?",Integer.class,f.sourceId));}finally{f.clear();}}
    @Test void disabledWorkerDoesNotReadTables(){var terms=mock(CoursePrivateContractTermMapper.class);var worker=new CoursePrivateOperationsWorker(terms,mock(CourseReservedWalletMapper.class),mock(CoursePrivateTermService.class),mock(CoursePrivateSettlementService.class),new CoursePrivateOperationsTime(java.time.Clock.system(java.time.ZoneId.of("Asia/Shanghai"))));worker.reconcile();verifyNoInteractions(terms);}
    @Test void twoWorkersReconcileSameExpiredPeriodOnce() throws Exception {var f=new CoursePrivateSettlementTransactionTest();try{f.setup();var id=f.buy("worker");f.complete(id);f.f.clock.advance(Duration.ofDays(30));var batch=mock(CoursePrivateContractTermMapper.class);when(batch.selectReconciliationBatch(0L,100)).thenReturn(List.of(f.f.current()));var time=new CoursePrivateOperationsTime(f.f.clock);var first=new CoursePrivateOperationsWorker(batch,f.f.f.wallets,f.f.service,f.service,time);var second=new CoursePrivateOperationsWorker(batch,f.f.f.wallets,f.f.service,f.service,time);org.springframework.test.util.ReflectionTestUtils.setField(first,"enabled",true);org.springframework.test.util.ReflectionTestUtils.setField(second,"enabled",true);var outcomes=f.f.f.concurrent(first::reconcile,second::reconcile);assertEquals(0,outcomes.stream().filter(RuntimeException.class::isInstance).count());assertEquals(1,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_term_settlement",Integer.class));assertNotNull(f.f.current().getFinalizedAt());}finally{f.clear();}}
}
